/**
 * The create/edit screen (`design/archetypes/form-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/form-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  derived,
  elementRef,
  presence,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/form-page.module.css'
import { Inline, type InlineProps } from '../layout/Inline'
import { PageHeader, type PageHeaderProps } from '../structure/PageHeader'

/** The create/edit screen: the inputs it takes, by the React member's prop names. */
export interface FormPageProps {
  description?: string
  title: string
}

/** The create/edit screen. */
@Component({
  selector: 'pm-form-page',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate, Inline, PageHeader],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="leadingAction" [pmSlotOf]="$"><ng-content select="[slot=leadingAction]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[attr.class]="e1()"
data-member="form-page"
><pm-page-header
[title]="e2()"
[description]="e3()"
></pm-page-header>
@if (e4()) {<!-- form -->
<form
[attr.class]="e5()"
[attr.novalidate]="e6()"
(submit)="h1($event)"
[pmRef]="form"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" />
<!-- actions -->
<div
[attr.class]="e7()"
>@if (e8()) {<!-- split -->
<div
[attr.class]="e9()"
><ng-container [pmSlotOutlet]="'leadingAction'" [pmSlotOf]="$" />
<!-- trailing -->
<div
[attr.class]="e10()"
><pm-inline
[gap]="e11()"
justify="end"
[wrap]="e12()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline></div></div>} @else {<pm-inline
[gap]="e13()"
justify="end"
[wrap]="e14()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline>}</div></form>} @else {<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" />
<!-- actions -->
<div
[attr.class]="e15()"
>@if (e16()) {<!-- split -->
<div
[attr.class]="e17()"
><ng-container [pmSlotOutlet]="'leadingAction'" [pmSlotOf]="$" />
<!-- trailing -->
<div
[attr.class]="e18()"
><pm-inline
[gap]="e19()"
justify="end"
[wrap]="e20()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline></div></div>} @else {<pm-inline
[gap]="e21()"
justify="end"
[wrap]="e22()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline>}</div>}</div>`,
})
export class FormPage {
  readonly description = input<FormPageProps['description']>(undefined)
  readonly title = input.required<FormPageProps['title']>()
  readonly onSubmit = output<void>({ alias: 'submit' })
  protected readonly $ = useMember({
    events: ['submit'],
    props: { description: () => this.description(), title: () => this.title() },
  })
  protected readonly $p = this.$.props
  protected readonly form = elementRef<HTMLElement>()
  protected readonly submit = derived(() => (event: Event) => {
    event.preventDefault()
    const invalid = this.form.value?.querySelector<HTMLElement>('[aria-invalid="true"]')
    if (invalid) {
      invalid.focus()
      return
    }
    this.$.emit(this.onSubmit, 'onSubmit')
  })

  protected e1() {
    return styles.page
  }

  protected e2(): PageHeaderProps['title'] {
    return this.$p.title
  }

  protected e3(): PageHeaderProps['description'] {
    return this.$p.description
  }

  protected e4() {
    return this.$.listening(this.onSubmit, 'onSubmit')
  }

  protected e5() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return styles.form
  }

  protected e6() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return presence(true)
  }

  protected h1($event: SubmitEvent): void {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return
    this.submit.value($event)
  }

  protected e7() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return styles.actions
  }

  protected e8() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return this.$.filled('leadingAction')
  }

  protected e9() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('leadingAction')) return undefined as never
    return styles.split
  }

  protected e10() {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('leadingAction')) return undefined as never
    return styles.trailing
  }

  protected e11(): InlineProps['gap'] {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('leadingAction')) return undefined as never
    return 3
  }

  protected e12(): InlineProps['wrap'] {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('leadingAction')) return undefined as never
    return true
  }

  protected e13(): InlineProps['gap'] {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (this.$.filled('leadingAction')) return undefined as never
    return 3
  }

  protected e14(): InlineProps['wrap'] {
    if (!this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (this.$.filled('leadingAction')) return undefined as never
    return true
  }

  protected e15() {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return styles.actions
  }

  protected e16() {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    return this.$.filled('leadingAction')
  }

  protected e17() {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('leadingAction')) return undefined as never
    return styles.split
  }

  protected e18() {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('leadingAction')) return undefined as never
    return styles.trailing
  }

  protected e19(): InlineProps['gap'] {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('leadingAction')) return undefined as never
    return 3
  }

  protected e20(): InlineProps['wrap'] {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (!this.$.filled('leadingAction')) return undefined as never
    return true
  }

  protected e21(): InlineProps['gap'] {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (this.$.filled('leadingAction')) return undefined as never
    return 3
  }

  protected e22(): InlineProps['wrap'] {
    if (this.$.listening(this.onSubmit, 'onSubmit')) return undefined as never
    if (this.$.filled('leadingAction')) return undefined as never
    return true
  }
}
